"""Generate crawlable static pages from content/profile.json. Python 3; no npm dependencies."""
import json, html, shutil, sys, zipfile, hashlib
import search_presence
from pathlib import Path
from xml.sax.saxutils import escape as xml
ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'dist'; D.mkdir(exist_ok=True)
P=json.loads((ROOT/'content/profile.json').read_text())
if '--public' in sys.argv: P['publicIndexing']=True
if '--site-url' in sys.argv: P['siteUrl']=sys.argv[sys.argv.index('--site-url')+1].rstrip('/')
H=html.escape
URL=P['siteUrl']
CSS_VERSION=hashlib.sha256((ROOT/'assets/style.css').read_bytes()).hexdigest()[:12]
JS_VERSION=hashlib.sha256((ROOT/'assets/app.js').read_bytes()).hexdigest()[:12]
shutil.copytree(ROOT/'assets',D/'assets',dirs_exist_ok=True,ignore=shutil.ignore_patterns('.*'))
shutil.copyfile(ROOT/'assets/Muzammil_Qazi_Resume.pdf',D/'Muzammil_Qazi_Resume.pdf')
def tags(items): return '<div class="tags">'+''.join('<span class="tag">'+H(i)+'</span>' for i in items)+'</div>'
def diagram(flow):
    rows=''
    for i,label in enumerate(flow):
        y=18+i*66
        rows+=f'<rect x="46" y="{y}" width="288" height="46" rx="6" fill="#fffef8" stroke="#bcc8ac"/><circle cx="70" cy="{y+23}" r="9" fill="#e1e9d3"/><text x="70" y="{y+26}" text-anchor="middle" font-size="8" fill="#496236">{i+1}</text><text x="92" y="{y+27}" font-size="12" fill="#34472c">{H(label)}</text>'
        if i<2: rows+=f'<path d="M190 {y+46}v20m-4-4 4 4 4-4" fill="none" stroke="#81996b"/>'
    return f'<svg viewBox="0 0 380 220" role="img" aria-label="Workflow: {H(" to ".join(flow))}" xmlns="http://www.w3.org/2000/svg" font-family="Arial,sans-serif">{rows}</svg>'
def hero_art():
    return '''<div class="hero-art"><div class="art-label">A PRACTICAL ENGINEERING MINDSET</div><svg viewBox="0 0 430 365" role="img" aria-label="Data engineering approach: ingest data, validate quality, and assist operations. Human review connects the workflow." xmlns="http://www.w3.org/2000/svg" font-family="Arial,sans-serif">
<defs><pattern id="grid" width="19" height="19" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#cbd4bd"/></pattern></defs><rect width="430" height="365" fill="url(#grid)"/>
<circle cx="215" cy="175" r="142" fill="none" stroke="#c6d0b6" stroke-dasharray="3 6"/><path d="M215 62v30M215 153v32M215 246v32M110 122H66v187h94" fill="none" stroke="#9bac85"/>
<rect x="109" y="31" width="212" height="61" rx="7" fill="#fffef7" stroke="#afbf9a"/><text x="130" y="56" font-size="10" fill="#6b7f56">01 / INGEST</text><text x="130" y="76" font-size="14" fill="#304729">Sources → Azure data pipelines</text>
<rect x="109" y="123" width="212" height="61" rx="7" fill="#fffef7" stroke="#afbf9a"/><text x="130" y="148" font-size="10" fill="#6b7f56">02 / VALIDATE</text><text x="130" y="168" font-size="14" fill="#304729">SQL checks &amp; reconciliation</text>
<rect x="109" y="216" width="212" height="61" rx="7" fill="#2c4531"/><text x="130" y="241" font-size="10" fill="#bfd6a5">03 / ASSIST</text><text x="130" y="261" font-size="14" fill="#eff4e7">AI-guided operational context</text>
<rect x="150" y="307" width="132" height="29" rx="15" fill="#e2e9d5" stroke="#b3c49b"/><text x="216" y="326" text-anchor="middle" font-size="10" fill="#4e6936">Human judgment, always</text><circle cx="66" cy="175" r="4" fill="#6c8550"/>
</svg><div class="art-bottom"><span>DATA FOUNDATIONS<br>Azure · SQL · PySpark</span><span>THOUGHTFUL AUTOMATION<br>Context · Clarity · Review</span></div></div>'''
def header(home=False):
    base='' if home else '/'
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Muzammil Qazi home"><span class="monogram" aria-hidden="true">mq.</span><span>Muzammil Qazi<small>Data engineering &amp; AI automation</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="primary-nav">Menu</button><label class="theme-picker"><span class="theme-dot" aria-hidden="true"></span><span class="sr-only">Color theme</span><select id="theme-select" aria-label="Color theme"><option value="champagne">Champagne</option><option value="pearl">Pearl</option><option value="aurora">Aurora</option><option value="rose">Rose</option></select></label><nav class="nav" id="primary-nav" aria-label="Primary navigation"><a href="{base}#live-projects">Live projects</a><a href="{base}#skills">Skills</a><a href="/notes/">Notes</a><a href="/about/">About</a><a href="{base}#experience">Experience</a><a class="nav-contact" href="/contact/">Let's connect <span aria-hidden="true">↗</span></a></nav></div></header>'''
def footer():
    return f'''<footer class="footer"><div class="wrap footer-inner"><span>© 2026 Muzammil Qazi · Pune, India</span><div class="footer-links"><a href="{H(P['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="/Muzammil_Qazi_Resume.pdf" download>Résumé ↓</a><a href="https://github.com/m-qazi99" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a href="/profile/">Profile &amp; sources</a><a href="/projects/">Project evidence</a><a href="#main">Back to top ↑</a></div></div></footer>'''
def contact():
    return f'''<section class="contact" id="contact" aria-labelledby="contact-title"><div class="wrap contact-top"><div><div class="eyebrow"><span class="dot"></span> Start a conversation</div><h2 id="contact-title">Have a data challenge?<br><em>Let's make it clearer.</em></h2><a class="email" href="mailto:{P['email']}">{P['email']} <span aria-hidden="true">↗</span></a></div><div class="contact-aside">For relevant roles, project discussions, consulting enquiries, or simply comparing notes on data and automation.<br><a class="text-link" href="{H(P['linkedin'])}" target="_blank" rel="noopener noreferrer">Connect on LinkedIn ↗</a><a class="text-link" href="/Muzammil_Qazi_Resume.pdf" download>Download résumé ↓</a></div></div></section>'''
def page(title,description,body,path='/',home=False):
    canonical=URL+path
    schema=search_presence.schema(P,title,description,path,home)
    indexing=('index,follow,max-image-preview:large' if P['publicIndexing'] else 'noindex,nofollow') if path!='/404.html' else 'noindex,follow'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{H(title)}</title><meta name="description" content="{H(description)}"><meta name="author" content="Muzammil Qazi"><meta property="og:locale" content="en_IN"><meta name="robots" content="{indexing}"><meta name="theme-color" content="#faf7ef"><script src="/assets/theme.js?v=1"></script><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:title" content="{H(title)}"><meta property="og:description" content="{H(description)}"><meta property="og:url" content="{canonical}"><meta property="og:site_name" content="Muzammil Qazi"><meta property="og:image" content="{URL}/assets/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Muzammil Qazi — Azure Data Engineering and AI Workflow Automation"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/assets/style.css?v={CSS_VERSION}"><link rel="preload" href="/assets/body.woff" as="font" type="font/woff" crossorigin><script type="application/ld+json">{json.dumps(schema)}</script><script defer src="/assets/app.js?v={JS_VERSION}"></script></head><body>{header(home)}{body}{footer()}</body></html>'''
from studio import hero_art, enhance, contact_form
cards=''
for p in P['projects']:
    cards+=f'''<article class="project"><div class="project-copy"><div class="project-top"><span class="project-num">{p['number']}</span><span>{H(p['category'])}</span></div><h3><a href="/work/{p['slug']}/">{H(p['title'])}</a></h3><p>{H(p['summary'])}</p>{tags(p['tools'])}<a class="text-link" href="/work/{p['slug']}/" aria-label="Read case study: {H(p['name'])}">Explore the case study <span aria-hidden="true">↗</span></a></div><div class="project-art">{diagram(p['flow'])}<span class="diagram-label">Workflow illustration · résumé-based summary</span></div></article>'''
caps=''.join(f'<article class="capability"><span class="cap-icon" aria-hidden="true">0{i+1}</span><h3>{H(c["title"])}</h3><p>{H(c["description"])}</p>{tags(c["tools"])}</article>' for i,c in enumerate(P['capabilities']))
roles=''.join(f'<article class="role"><div class="role-head"><h3>{H(r["role"])}</h3><time>{H(r["dates"])}</time></div><p class="focus">{H(r["focus"])}</p><ul>'+''.join('<li>'+H(x)+'</li>' for x in r['points'])+'</ul></article>' for r in P['experience'])
edu=''.join(f'<div><h4>{H(e["degree"])}</h4><p>{H(e["school"])}<br>{H(e["dates"])}</p></div>' for e in P['education'])
body=f'''<main id="main"><section class="hero"><div class="wrap"><div class="hero-grid"><div class="reveal"><div class="eyebrow"><span class="dot"></span> Muzammil Qazi / Pune, India</div><h1>Reliable data.<br>Practical AI.<br><em>Less busywork.</em></h1><div class="hero-role">AZURE DATA ENGINEER · AI WORKFLOW AUTOMATION</div><p class="intro">{H(P['introduction'])}</p>{search_presence.identity_intro()}<div class="actions"><a class="button primary" href="#live-projects">Explore my work <span class="arrow" aria-hidden="true">↗</span></a><a class="text-link" href="/Muzammil_Qazi_Resume.pdf" download>Download résumé ↓</a></div><div class="hero-note"><span class="dot"></span> Open to relevant roles &amp; project conversations</div></div>{hero_art()}</div><div class="discipline-strip"><span><b>01</b> Azure data engineering</span><span><b>02</b> Data quality &amp; reliability</span><span><b>03</b> AI-assisted workflows</span></div></div></section>
<section class="section white-section" id="work" aria-labelledby="work-title"><div class="wrap"><div class="section-head"><div><div class="eyebrow">01 / Selected work</div><h2 id="work-title">Real problems.<br>Practical approaches.</h2></div><p>Projects at the intersection of data engineering and everyday operations. Explore the problem, my contribution, and the implementation described in my résumé.</p></div><div class="project-list">{cards}</div><p class="note">These earlier résumé-based summaries are separate from the five independent live tools above. No employer deployment or benchmark claims are implied.</p></div></section>
<section class="section" id="expertise" aria-labelledby="expertise-title"><div class="wrap"><div class="section-head"><div><div class="eyebrow">04 / How I contribute</div><h2 id="expertise-title">A useful bridge between<br>data and operations.</h2></div><p>A practical toolkit for moving data, checking it, and making the work around it easier to manage.</p></div><div class="capability-grid">{caps}</div><div class="learning"><strong>Currently deepening</strong><p>{H(' · '.join(P['learning']))}<br>Exploratory and developing skills, separate from my core delivery experience.</p></div></div></section>
<section class="section white-section" id="about" aria-labelledby="about-title"><div class="wrap about-grid"><div><div class="eyebrow">05 / A little context</div><div class="section-head"><h2 id="about-title">An operational eye.<br>An engineering mindset.</h2></div><div class="about-mark" aria-hidden="true"><span>mq.</span></div></div><div class="about-copy">{''.join('<p>'+H(x)+'</p>' for x in P['about'])}<div class="about-facts"><div><strong>Pune, India</strong>Based in Maharashtra</div><div><strong>Data + automation</strong>Current professional direction</div></div></div></div></section>
<section class="section" id="experience" aria-labelledby="experience-title"><div class="wrap"><div class="section-head"><div><div class="eyebrow">06 / Experience</div><h2 id="experience-title">Built on enterprise experience.</h2></div><a class="text-link" href="/Muzammil_Qazi_Resume.pdf" download>Get the concise résumé ↓</a></div><div class="timeline"><div><h3 class="company">Cognizant</h3><p class="company-meta">Technology Solutions · Pune<br>March 2022 — Present</p></div><div class="roles">{roles}</div></div><div class="education"><h3>Education</h3><div class="education-items">{edu}</div></div></div></section>
<section class="section collaborate" aria-labelledby="collab-title"><div class="wrap"><div class="section-head"><div><div class="eyebrow">07 / Ways to work together</div><h2 id="collab-title">Bring the problem.<br>Let's find a useful next step.</h2></div><p>Interested in teams and collaborations where reliable data and thoughtful automation can make everyday work better.</p></div><div class="collab-options"><article class="collab-option"><span>01 / TEAMS &amp; RECRUITERS</span><h3>Data &amp; automation roles</h3><p>Azure data engineering, data quality, and workflow automation opportunities aligned with my experience.</p></article><article class="collab-option"><span>02 / PROJECT DISCUSSIONS</span><h3>Practical automation</h3><p>Discuss a defined data-validation, diagnostic, documentation, or workflow problem and explore whether there's a fit.</p></article><article class="collab-option"><span>03 / PROFESSIONAL CONNECTIONS</span><h3>Ideas worth exchanging</h3><p>Connect around Azure data platforms, operational reliability, and the practical use of AI in engineering teams.</p></article></div><a class="button" href="mailto:{P['email']}?subject=Data%20and%20automation%20conversation">Start a conversation <span aria-hidden="true">↗</span></a></div></section>
<section class="section" aria-labelledby="faq-title"><div class="wrap faq-layout"><div><div class="eyebrow">08 / Quick answers</div><div class="section-head"><h2 id="faq-title">A few useful details.</h2></div></div><div><details><summary>What opportunities are you interested in?</summary><p>Azure data engineering and practical AI workflow automation, including data quality and intelligent data operations. I am based in Pune and interested in remote opportunities that can employ someone in India. Working arrangements and project scope can be discussed directly.</p></details><details><summary>How do your AI projects fit your experience?</summary><p>They apply AI to familiar operational problems: interpreting pipeline errors, generating data-validation SQL, and retrieving guidance from runbooks. The knowledge assistant is a proof of concept. Each case study states what the available evidence supports.</p></details><details><summary>What's the best way to get in touch?</summary><p>Email <a href="mailto:{P['email']}">{P['email']}</a> with a role description or a short outline of the problem. You can also connect via <a href="{H(P['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn</a>.</p></details></div></div></section>{contact()}</main>'''
body=enhance(body,P)
(D/'index.html').write_text(page('Muzammil Qazi | Azure Data Engineer & AI Workflow Automation','Muzammil Qazi is an Azure data engineer in Pune, India, working across data pipelines, SQL validation, operational reliability and practical AI workflow automation.',body,home=True))
for i,p in enumerate(P['projects']):
    sections=[('The problem',p['problem']),('My contribution',p['contribution']),('Implementation',p['implementation']),('Documented outcome',p['outcome']),('Scope & evidence',p['boundary']),('A useful next conversation',p['discussion'])]
    nxt=P['projects'][(i+1)%len(P['projects'])]
    b=f'''<main id="main"><section class="case-hero"><div class="wrap"><a class="back" href="/#work">← Back to selected work</a><div class="eyebrow">{p['number']} / {H(p['category'])}</div><h1>{H(p['name'])}</h1><p class="lead">{H(p['summary'])}</p><div class="case-diagram">{diagram(p['flow'])}</div></div></section><div class="wrap"><div class="case-grid"><aside class="case-aside"><h2>Project context</h2><p>Résumé-based project summary<br>Updated October 2026</p><h2>Tools &amp; concepts</h2>{tags(p['tools'])}<p>Workflow diagrams illustrate the documented approach, rather than a deployed system.</p></aside><div class="case-content">{''.join('<section><h2>'+H(h)+'</h2><p>'+H(t)+'</p></section>' for h,t in sections)}<a class="button primary" href="mailto:{P['email']}?subject=Discuss%20{p['slug']}">Discuss this project <span aria-hidden="true">↗</span></a><div class="next-project"><span>NEXT CASE STUDY</span><a href="/work/{nxt['slug']}/">{H(nxt['name'])} ↗</a></div></div></div></div>{contact()}</main>'''
    path=f'/work/{p["slug"]}/'; out=D/path.strip('/');out.mkdir(parents=True,exist_ok=True)
    (out/'index.html').write_text(page(p['name']+' | Muzammil Qazi',p['summary'],b,path=path))
for route,title,content in [
 ('about','About Muzammil Qazi', '<main id="main"><section class="section case-hero"><div class="wrap"><div class="eyebrow">BEHIND THE WORK</div><h1>An operational eye.<br><em>An engineering mindset.</em></h1><div class="about-copy">'+''.join('<p>'+H(t)+'</p>' for t in P['about'])+'</div><div class="education"><h2>Education</h2>'+edu+'</div><a class="button primary" href="/#experience">Explore my experience ↗</a></div></section>'+contact()+'</main>'),
 ('contact','Contact Muzammil Qazi','<main id="main"><section class="case-hero wrap"><div class="eyebrow">CONTACT / PUNE, INDIA</div><h1>Good work starts<br><em>with a conversation.</em></h1><p class="lead">Data engineering roles, practical automation, or an idea worth exploring.</p></section>'+contact()+contact_form(P)+'</main>')]:
 out=D/route;out.mkdir(exist_ok=True);(out/'index.html').write_text(page(title,title+' — data engineering and AI workflow automation in Pune.',content,path='/'+route+'/'))
extra_routes=search_presence.build(P,D,page)
urls=['/','/about/','/contact/']+[f'/work/{p["slug"]}/' for p in P['projects']]+extra_routes+['/'+p['slug']+'/' for p in search_presence.PROJECTS]
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+xml(URL+u)+'</loc></url>' for u in urls)+'</urlset>')
robot_rules='User-agent: *\n'+('Allow: /\n' if P['publicIndexing'] else 'Disallow: /\n')
if P['publicIndexing']:
    for agent in ['Googlebot','bingbot','OAI-SearchBot','Claude-SearchBot','PerplexityBot']:
        robot_rules+='\nUser-agent: '+agent+'\nAllow: /\n'
(D/'robots.txt').write_text('# Public portfolio. Search access is not a ranking guarantee.\n'+robot_rules+'\nSitemap: '+URL+'/sitemap.xml\n')
(D/'404.html').write_text(page('Page not found | Muzammil Qazi','Return to Muzammil Qazi’s portfolio.', '<main id="main" class="wrap case-hero"><div class="eyebrow">404 / Page not found</div><h1>Let’s get you back on track.</h1><p>This page could not be found.</p><a class="button primary" href="/">Return to portfolio ↗</a></main>',path='/404.html'))
(D/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: SAMEORIGIN\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src \'self\'; img-src \'self\' data:; font-src \'self\'; script-src \'self\'; style-src \'self\'; base-uri \'self\'; form-action \'none\'\n')
# Portable source download excludes hosting identity, Git data, and credentials.
with zipfile.ZipFile(D/'portfolio-source.zip','w',zipfile.ZIP_DEFLATED) as z:
    for folder in ['content','scripts','assets']:
        for file in (ROOT/folder).rglob('*'):
            if file.is_file() and not file.name.startswith('.') and file.suffix not in ['.ttf','.jpg'] and '__pycache__' not in str(file):z.write(file,file.relative_to(ROOT))
    for name in ['README.md','package.json']:
        if (ROOT/name).exists():z.write(ROOT/name,name)
print(f'Built home, {len(P["projects"])} case studies, 404, metadata, sitemap, robots and source archive. Indexing: {P["publicIndexing"]}')

# Mirror the validated static output to the GitHub Pages publishing directory.
shutil.copytree(D,ROOT/'docs',dirs_exist_ok=True)
(ROOT/'docs/.nojekyll').touch()
